using System;
using System.IO;
using System.Net;

// Minimal replacement for the abandoned PortableRazor 1.3 library (a 2014 PCL).
// The *.cs files next to the *.cshtml templates were generated by Xamarin Studio's
// RazorTemplatePreprocessor and derive from PortableRazor.ViewBase / use
// PortableRazor.Web.Mvc.HtmlString, so the same names are kept here to avoid
// touching the generated code.
namespace PortableRazor
{
    public interface IHtmlString
    {
        string ToHtmlString();
    }

    public abstract class ViewBase
    {
        private TextWriter _writer;

        public string GenerateString()
        {
            using var sw = new StringWriter();
            Generate(sw);
            return sw.ToString();
        }

        public void Generate(TextWriter writer)
        {
            _writer = writer;
            try
            {
                Execute();
            }
            finally
            {
                _writer = null;
            }
        }

        public abstract void Execute();

        protected void WriteLiteral(string value) => _writer.Write(value);

        protected static void WriteLiteralTo(TextWriter writer, string value) => writer.Write(value);

        protected void Write(object value) => WriteTo(_writer, value);

        protected static void WriteTo(TextWriter writer, object value)
        {
            switch (value)
            {
                case null:
                    return;
                case Action<TextWriter> helper:
                    helper(writer);
                    return;
                case IHtmlString html:
                    writer.Write(html.ToHtmlString());
                    return;
                default:
                    writer.Write(WebUtility.HtmlEncode(value.ToString()));
                    return;
            }
        }

        protected void WriteAttribute(string name, string prefix, string suffix, params Tuple<string, object, bool>[] values)
            => WriteAttributeTo(_writer, name, prefix, suffix, values);

        // Based on System.Web.WebPages.WebPageExecutingBase (Apache License 2.0).
        protected static void WriteAttributeTo(TextWriter writer, string name, string prefix, string suffix, params Tuple<string, object, bool>[] values)
        {
            if (values.Length == 0)
            {
                writer.Write(prefix);
                writer.Write(suffix);
                return;
            }

            var first = true;
            var wroteSomething = false;

            foreach (var (attPrefix, value, isLiteral) in values)
            {
                if (value == null)
                {
                    continue;
                }

                object output = value;
                if (value is bool b)
                {
                    if (!b)
                    {
                        continue;
                    }
                    output = name;
                }

                writer.Write(first ? prefix : attPrefix);
                first = false;

                if (isLiteral)
                {
                    writer.Write(output);
                }
                else
                {
                    WriteTo(writer, output);
                }
                wroteSomething = true;
            }

            if (wroteSomething)
            {
                writer.Write(suffix);
            }
        }
    }
}

namespace PortableRazor.Web.Mvc
{
    public class HtmlString : IHtmlString
    {
        private readonly string _value;

        public HtmlString(string value) => _value = value;

        public string ToHtmlString() => _value;

        public override string ToString() => _value;
    }
}
